#pragma once
#include <cstdint>

// Compress all the sound generated by a batch of DS frames into one output frame.
// Averaging each group keeps both stereo channels and avoids a growing playback backlog.
inline int AudioFastForward(int16_t* samples, int frames, int speed)
{
    if (speed <= 1) return frames;
    const int out = frames / speed;
    for (int i = 0; i < out; ++i)
        for (int channel = 0; channel < 2; ++channel)
        {
            int64_t sum = 0;
            for (int j = 0; j < speed; ++j)
                sum += samples[(i * speed + j) * 2 + channel];
            samples[i * 2 + channel] = static_cast<int16_t>(sum / speed);
        }
    return out;
}
